    /** Evaluates [predicate] with the domain's single implementation [predicates]. */
    @Suppress("CyclomaticComplexMethod")
    fun holds(
        predicate: ResultPredicate,
        predicates: ResultPredicates,
        facts: ResultFacts,
    ): Boolean =
        when (predicate) {
            ResultPredicate.TECHNOLOGIST_VALIDATED -> predicates.technologistValidated(facts)
            ResultPredicate.SPECIMEN_USABLE -> predicates.specimenUsable(facts)
            ResultPredicate.QC_ALLOWS_RELEASE -> predicates.qcAllowsRelease(facts)
            ResultPredicate.CRITICAL_VALUE_FLAGGED -> predicates.criticalValueFlagged(facts)
            ResultPredicate.NO_CRITICAL_VALUE_FLAGGED -> predicates.noCriticalValueFlagged(facts)
            ResultPredicate.PATIENT_DISCHARGED -> predicates.patientDischarged(facts)
            ResultPredicate.PATIENT_NOT_DISCHARGED -> predicates.patientNotDischarged(facts)
            ResultPredicate.CORRECTION_REASON_ENTERED -> predicates.correctionReasonEntered(facts)
            ResultPredicate.CANCELLATION_REASON_ENTERED -> predicates.cancellationReasonEntered(facts)
            ResultPredicate.ERROR_REASON_ENTERED -> predicates.errorReasonEntered(facts)
            ResultPredicate.PRIVILEGED_AND_AUDITED -> predicates.privilegedAndAudited(facts)
            ResultPredicate.AUTOVERIFICATION_ACTIVE -> predicates.autoverificationActive(facts)
            ResultPredicate.AUTOVERIFICATION_RULES_PASSED -> predicates.autoverificationRulesPassed(facts)
        }

    /** Applies [command] in [state] with [facts]; never changes state unless exactly one guard holds. */
    fun fire(
        state: ResultState,
        command: ResultCommand,
        predicates: ResultPredicates,
        facts: ResultFacts,
    ): Outcome<ResultState, ResultCommand, ResultPredicate, ResultEffect> = spec.fire(state, command) { holds(it, predicates, facts) }
}
